import sys
p=sys.argv[1]; s=open(p,encoding='utf-8').read()
def R(a,b,n=1):
    global s
    assert s.count(a)==n,(a[:80],s.count(a)); s=s.replace(a,b)
# state
R("steps:'6000',cal:false,done:[],skip:[]","steps:'6000',min:'20',cal:false,done:[],part:[],skip:[]")
# walk item: anchored, duration-based, talk test
R("""let wt=m.when==='morning'?'07:00':'17:30',adj='';
 if(m.where==='outdoor'&&mpT(wt)>=16){wt='07:00';adj=L('下午 4 点后可能有雷雨，挪到早上','Thunderstorms likely after 4 pm, moved to the morning')}
 const wa=low?L('慢走 20 分钟','Slow walk, 20 minutes'):m.where==='indoor'?L('社区中心健身操 30 分钟','Exercise class at the community centre, 30 minutes'):L('公园连道快走 30 分钟','Brisk walk on the park connector, 30 minutes');
 const wb=low?L('昨晚血氧有一段偏低，今天轻松一点','Your oxygen dipped last night, so take it easy today'):L('心率 100–125 次/分，能说话不能唱歌','Heart rate 100–125, enough to talk but not sing');
 if(m.fix){out.push({id:'walk',t:'18:30',k:'sug',a:L('社区中心健身操 30 分钟','Exercise class at the community centre, 30 minutes'),b:L('早上错过了，改成室内','Missed this morning, moved indoors'),adj:''})}else out.push({id:'walk',t:wt,k:'sug',a:wa,b:wb,adj});""",
"""const mn=+m.min,am=m.when==='morning';let wt=am?mpS(mpT(m.wake)+1):'19:00',adj='',anc=am?L('早饭后','After breakfast'):L('晚饭后','After dinner');
 if(m.where==='outdoor'&&!am){wt=mpS(mpT(m.wake)+1);anc=L('早饭后','After breakfast');adj=L('傍晚可能有雷雨，今天挪到早饭后','Thunderstorms likely this evening, so moved to after breakfast today')}
 const wa=low?L('慢走 '+Math.min(mn,20)+' 分钟','Slow walk, '+Math.min(mn,20)+' minutes'):m.where==='indoor'?L('室内健身操 '+mn+' 分钟','Indoor exercise class, '+mn+' minutes'):L('公园连道快走 '+mn+' 分钟','Brisk walk on the park connector, '+mn+' minutes');
 const wb=low?L('昨晚血氧有一段偏低，今天轻松一点','Your oxygen dipped last night, so take it easy today'):anc+L(' · 约 '+(mn*100).toLocaleString('en-US')+' 步 · 有点喘、还能说话',' · about '+(mn*100).toLocaleString('en-US')+' steps · a little out of breath, still able to talk');
 if(m.fix){out.push({id:'walk',t:'19:00',k:'sug',a:L('室内健身操 '+mn+' 分钟','Indoor exercise class, '+mn+' minutes'),b:L('早上错过了，晚饭后改成室内','Missed this morning, moved indoors after dinner'),adj:''})}else out.push({id:'walk',t:wt,k:'sug',a:wa,b:wb,adj});""")
# row: tiny version + kind skip text
R("""function mpRow(x,now){const m=MP(),past=mpT(x.t)<=now,done=m.done.includes(x.id)||(past&&x.k==='base')""",
"""function mpRow(x,now){const m=MP(),past=mpT(x.t)<=now,part=m.part.includes(x.id),done=part||m.done.includes(x.id)||(past&&x.k==='base')""")
R("""${past?'':`<button data-act="mplater" data-v="${x.id}">${med?L('晚一点','A bit later'):L('晚 1 小时','1 hour later')}</button>`}""",
"""${x.id==='walk'?`<button data-act="mppart" data-v="walk">${L('走了 5 分钟','Did 5 min')}</button>`:past?'':`<button data-act="mplater" data-v="${x.id}">${med?L('晚一点','A bit later'):L('晚 1 小时','1 hour later')}</button>`}""")
R("""<div class="ss">${skip?(med?L('记下了：没做','Noted: not done'):L('今天不做了','Skipped today')):x.b}</div>""",
"""<div class="ss">${skip?(med?L('记下了：没做','Noted: not done'):L('今天不做了 · 没关系，明天接着来','Skipped today. That’s fine, pick it up tomorrow')):part?L('走了 5 分钟，也算数','5 minutes. That still counts'):x.b}</div>""")
R("""fix=miss&&x.id==='walk'&&!m.fix?`<div class="adj">${L('错过了。傍晚有雷雨，改成室内健身操？','Missed. Rain this evening: switch to an indoor class?')} <button class="link" data-act="mpfix" style="font-size:13px;min-height:0;padding:0 0 0 4px">${L('改到 18:30','Move to 6:30 pm')}</button></div>`""",
"""fix=miss&&x.id==='walk'&&!m.fix?`<div class="adj">${L('错过了。傍晚有雷雨，晚饭后改成室内健身操？','Missed. Rain this evening: an indoor class after dinner instead?')} <button class="link" data-act="mpfix" style="font-size:13px;min-height:0;padding:0 0 0 4px">${L('改到 19:00','Move to 7 pm')}</button></div>`""")
