R("""`<h1 class="h1" style="font-size:26px">${L('你喜欢怎么动？','How do you like to move?')}</h1><div class="h3">${L('在哪','Where')}</div><div class="mpchips">${ch('where','outdoor',L('户外：公园连道、组屋楼下','Outdoors: park connector, round the block'))}${ch('where','indoor',L('室内：社区中心、家里','Indoors: community centre, at home'))}</div><div class="h3">${L('什么时候','When')}</div><div class="mpchips">${ch('when','morning',L('早上','Morning'))}${ch('when','evening',L('傍晚','Evening'))}</div><div class="h3">${L('每天走多少步','Daily steps goal')}</div><div class="mpchips">${['4000','6000','8000'].map(v=>ch('steps',v,(+v).toLocaleString('en-US')+L(' 步',' steps'))).join('')}</div><p class="sm mu">${L('下雨、空气不好（PSI 超过 100）或太热时，会自动帮你挪时间或换室内。','When it rains, the air is poor (PSI above 100) or it is too hot, we move it or switch indoors for you.')}</p>`""",
"""`<h1 class="h1" style="font-size:26px">${L('每天怎么动？','How will you move each day?')}</h1>${ssl()}<div class="h3">${L('快走接在哪件事后面','Walk right after')}</div><div class="mpchips">${ch('when','morning',L('早饭后','Breakfast'))}${ch('when','evening',L('晚饭后','Dinner'))}</div><div class="h3">${L('每次走多久','How long each time')}</div><div class="mpchips">${['10','20','30'].map(v=>ch('min',v,v+L(' 分钟',' min'))).join('')}</div><div class="h3">${L('在哪走','Where')}</div><div class="mpchips">${ch('where','outdoor',L('户外：公园连道、组屋楼下','Outdoors: park connector, round the block'))}${ch('where','indoor',L('室内：社区中心、家里','Indoors: community centre, at home'))}</div><div class="card" style="padding:14px 16px;background:var(--sf2)"><div class="h3">${L('你的做法','Your plan')}</div><p class="p" style="margin-top:4px">${L((m.when==='morning'?'早饭后':'晚饭后')+'，'+(m.where==='indoor'?'做室内健身操 ':'去公园连道快走 ')+m.min+' 分钟（约 '+(m.min*100).toLocaleString('en-US')+' 步）。不想动的日子，走 5 分钟也算。','After '+(m.when==='morning'?'breakfast':'dinner')+', '+(m.where==='indoor'?'an indoor exercise class':'a brisk walk on the park connector')+' for '+m.min+' minutes (about '+(m.min*100).toLocaleString('en-US')+' steps). On days you don’t feel like it, 5 minutes still counts.')}</p></div><p class="sm mu">${L('下雨、空气不好（PSI 超过 100）或太热时，会自动帮你挪时间或换室内。','When it rains, the air is poor (PSI above 100) or it is too hot, we move it or switch indoors for you.')} <button class="link" data-act="mphow" style="font-size:13px;min-height:0;padding:0">${L('怎么养成一个习惯 ›','How habits stick ›')}</button></p>`""")
