R("""<div class="card"><div class="between"><span class="h3">${L('我自己的习惯','My own habits')}</span><button class="link" data-go="mpsetup:own">${L('改一改','Change')}</button></div><div style="margin-top:4px">${mpItems().filter(x=>['walk','phone','bed'].includes(x.id)).map(x=>mpRow(x,S.hour)).join('')}</div><p class="sm mu" style="margin:6px 0 0">${L('连诊所前就有的作息，继续由你自己安排。医生的计划优先。吃药、量血压和目标都以医生的为准；医生如果安排了运动，会替换你自己的散步。','Your routine from before you linked is still yours to arrange. Your doctor’s plan comes first: medicines, BP checks and targets follow your doctor. If your doctor sets exercise, it replaces your own walk.')}</p></div>""",
"""<div class="card"><div class="between"><span class="h3">${L('我自己的习惯','My own habits')}</span><button class="link" data-go="mpsetup:own">${L('改一改','Change')}</button></div>${(()=>{const m=MP(),now=S.tm==='morning'?1240:3920,g=+m.steps;return `<div style="margin-top:8px"><div class="between"><span class="p">${L('今天 ','Today ')}<b class="num">${now.toLocaleString('en-US')}</b> / ${g.toLocaleString('en-US')} ${L('步','steps')}</span><span class="sm mu">${L('这周 5/7 晚 '+m.bed+' 前上床','In bed by '+m.bed+' 5 of 7 nights')}</span></div><div style="height:8px;border-radius:4px;background:var(--line);margin-top:6px;overflow:hidden"><i style="display:block;height:100%;width:${Math.min(100,now/g*100).toFixed(0)}%;background:var(--act)"></i></div></div>`})()}<div style="margin-top:4px">${mpItems().filter(x=>['walk','phone','bed'].includes(x.id)).map(x=>mpRow(x,S.hour)).join('')}</div>${lvlUp()}<p class="sm mu" style="margin:6px 0 0">${L('医生的计划优先。医生如果安排了运动，会替换你自己的散步。','Your doctor’s plan comes first. If your doctor sets exercise, it replaces your own walk.')}</p></div>""")
