R("""    mpfix(){MP().fix=true;toast(L('已改到 18:30 室内','Moved to 6:30 pm, indoors'));render()},""",
"""    mpfix(){MP().fix=true;toast(L('已改到 19:00 室内','Moved to 7 pm, indoors'));render()},
    mppart(){const m=MP();if(!m.part.includes(v))m.part.push(v);m.skip=m.skip.filter(x=>x!==v);toast(L('5 分钟也算，明天接着来','5 minutes counts. See you tomorrow'));render()},
    mpstp(){const m=MP();m.steps=String(Math.max(2000,Math.min(12000,+m.steps+(+v))));render()},
    mplvl(){const m=MP();m.lvl=v;if(v==='up'){m.steps=String(+m.steps+500);toast(L('从明天起，每天 '+(+m.steps).toLocaleString('en-US')+' 步','From tomorrow: '+(+m.steps).toLocaleString('en-US')+' steps a day'))}else toast(L('好，先保持。两周后再问你','OK, keeping it. We’ll ask again in two weeks'));render()},
    mphow(){sheet(`<div class="stack" style="gap:10px"><h2 class="h2" style="font-size:20px">${L('怎么养成一个习惯','How habits stick')}</h2><div class="kv"><div><span>${L('1 挂在已有的事后面','1 Tie it to something you already do')}</span></div><div><span class="sm mu">${L('“晚饭后就下楼走”比“每天要运动”容易记住。','“After dinner, I walk downstairs” is easier to keep than “exercise daily”.')}</span></div><div><span>${L('2 先小，后大','2 Start small, then grow')}</span></div><div><span class="sm mu">${L('先定大多数日子做得到的量。不想动的日子，走 5 分钟也算。','Pick an amount you can do on most days. On off days, 5 minutes counts.')}</span></div><div><span>${L('3 让它看得见','3 Make it visible')}</span></div><div><span class="sm mu">${L('圆环满一圈、点一下“完成”，就是记录。','A full ring or one tap on Done is your record.')}</span></div><div><span>${L('4 断一天没关系','4 Missing a day is fine')}</span></div><div><span class="sm mu">${L('别连着断两天就好。','Just try not to miss two in a row.')}</span></div><div><span>${L('5 稳了再加','5 Add more once it’s steady')}</span></div><div><span class="sm mu">${L('连续两周每周做到 5 天，我们会问你要不要加一点；你说了算。','After two weeks of 5+ days, we’ll ask if you want a bit more. Your call.')}</span></div></div><p class="sm mu" style="margin:0">${L('研究里，一个新习惯变得不用想，平均要两个多月，快的不到 3 周，慢的要大半年。慢一点很正常。','In studies, a new habit took a little over two months on average to feel automatic: under 3 weeks for some, most of a year for others. Slow is normal.')}</p></div>`)},""")
